<script setup>
import { ref, onMounted, watch, computed } from 'vue';
import { supabase } from '../supabase';
import { getBranchName } from '../lib/useBranches';
import HelpGuide from '../components/HelpGuide.vue';

const props = defineProps({
  branchId: [String, Number]
});

const todaySchedules = ref([]);
const pendingEvaluations = ref([]);
const teacherStats = ref([]);
const lowBalanceStudents = ref([]);
const unpaidCourses = ref([]);

const branchName = computed(() => {
  return getBranchName(props.branchId);
});

const pendingAttendanceCount = computed(() => {
  return todaySchedules.value.filter(s => s.status === 'scheduled').length;
});

const totalSessionsThisMonth = computed(() => {
  return teacherStats.value.reduce((acc, curr) => acc + curr.count, 0);
});

const formatTime = (timeStr) => {
  // start_time is already a simple "HH:MM" string
  return timeStr || '--:--';
};

const loadData = async () => {
  if (!props.branchId) return;

  // Load low balance and unpaid alerts directly from the AlertController backend
  const session = JSON.parse(localStorage.getItem('alltrue_session') || '{}');
  const token = session?.access_token || '';
  const baseUrl = import.meta.env.VITE_API_BASE || '/api';

  try {
    const alertsResp = await fetch(`${baseUrl}/v1/alerts/tuition`, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json',
      }
    });

    if (alertsResp.ok) {
      const alertsJson = await alertsResp.json();
      lowBalanceStudents.value = (alertsJson.low_balance || []).filter(c => c.student_name).map(c => ({
        id: c.class_id,
        name: `${c.student_name} — ${getSubjectLabel(c.SubjectID) || 'Math'}`,
        remaining_lessons: c.RemainingSessions || 0
      }));
    }
  } catch (err) {
    console.error('Failed to load alerts:', err);
  }

  // Find unpaid courses
  const { data: unpaidData } = await supabase
    .from('student-classes')
    .select('*, student:students(name)')
    .eq('branch_id', props.branchId)
    .eq('payment_status', 'unpaid');

  unpaidCourses.value = (unpaidData || [])
    .filter(c => c.status !== 'inactive')
    .map(c => ({
      id: c.id,
      student_name: c.student?.name || '?',
      subject: c.subject
    }));

  // Today's schedules: filter by schedule_date or day_of_week
  const today = new Date().toISOString().split('T')[0];
  const todayDow = new Date().getDay() || 7; // 1=Mon..7=Sun

  // Try schedule_date first, then fall back to day_of_week
  const { data: dateSchedules } = await supabase
    .from('schedules')
    .select('*')
    .eq('branch_id', props.branchId)
    .eq('schedule_date', today);

  const { data: dowSchedules } = await supabase
    .from('schedules')
    .select('*')
    .eq('branch_id', props.branchId)
    .eq('day_of_week', todayDow)
    .is('schedule_date', null);

  const allTodaySchedules = [...(dateSchedules || []), ...(dowSchedules || [])];
  // Deduplicate by id and filter only active statuses
  const seenIds = new Set();
  todaySchedules.value = allTodaySchedules
    .filter(s => {
      if (seenIds.has(s.id)) return false;
      seenIds.add(s.id);
      return s.status === 'scheduled' || s.status === 'attended';
    })
    .sort((a, b) => (a.start_time || '').localeCompare(b.start_time || ''));

  // Pending evaluations with schedule join for branch filtering
  const { data: evaluations } = await supabase
    .from('evaluations')
    .select('*, schedules(*)')
    .eq('status', 'pending');

  // Filter evaluations whose schedule belongs to this branch
  pendingEvaluations.value = (evaluations || []).filter(ev => {
    if (!ev.schedules) return false;
    return ev.schedules.branch_id === props.branchId || !props.branchId;
  });

  calculateTeacherStats();
};

const getSubjectLabel = (val) => {
  const map = {
    '1': '國文', '2': '英文', '3': '數學',
    'Chinese': '國文', 'English': '英文', 'Math': '數學'
  };
  return map[val] || val;
};

const calculateTeacherStats = async () => {
  try {
    const now = new Date();
    const startDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`;
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    const endDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

    const session = JSON.parse(localStorage.getItem('alltrue_session') || '{}');
    const token = session?.access_token || '';
    const baseUrl = import.meta.env.VITE_API_BASE || '/api';

    const params = new URLSearchParams({ start: startDate, end: endDate });
    const res = await fetch(`${baseUrl}/v1/finance/subject-units?${params}`, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json',
      }
    });

    if (!res.ok) return;
    const json = await res.json();

    // Map to dashboard summary format (teacher name + subject count)
    teacherStats.value = (json.teachers || []).map(t => ({
      id: t.teacher_id,
      name: t.teacher_name,
      subject: `科目數: ${t.subject_count_with}`,
      count: t.total_hours,
    }));
  } catch (e) {
    console.error('Failed to load teacher stats:', e);
  }
};

const markAttended = async (schedule) => {
  const { error } = await supabase.from('schedules').update({ status: 'attended' }).eq('id', schedule.id);
  if (!error) loadData();
};

const markCancelled = async (schedule) => {
  if (!confirm('確定取消?')) return;
  const { error } = await supabase.from('schedules').update({ status: 'cancelled' }).eq('id', schedule.id);
  if (!error) loadData();
};

const approveEvaluation = async (evalItem) => {
  if (!confirm('確認核准並扣堂?')) return;

  const { error } = await supabase.from('evaluations').update({ status: 'approved', approved_at: new Date() }).eq('id', evalItem.id);
  if (error) return;

  await supabase.from('schedules').update({ status: 'completed' }).eq('id', evalItem.schedule_id);

  // Deduct from per-course remaining_sessions instead of per-student total
  const { data: schedule } = await supabase.from('schedules').select('student_id, subject, deduction, student_course_id').eq('id', evalItem.schedule_id).single();
  if (schedule) {
    const deduction = schedule.deduction || 1;

    // Try to find the specific course by student_course_id first, then by student_id + subject
    let courseQuery;
    if (schedule.student_course_id) {
      courseQuery = await supabase.from('student-classes').select('id, remaining_sessions').eq('id', schedule.student_course_id).single();
    } else {
      courseQuery = await supabase.from('student-classes').select('id, remaining_sessions').eq('student_id', schedule.student_id).eq('subject', schedule.subject).single();
    }

    if (courseQuery.data) {
      const newRemaining = (courseQuery.data.remaining_sessions || 0) - deduction;
      await supabase.from('student-classes').update({ remaining_sessions: Math.max(0, newRemaining) }).eq('id', courseQuery.data.id);
    }
  }
  loadData();
};

watch(() => props.branchId, loadData);
onMounted(loadData);
</script>

